import {cases} from './shared.mjs';
const select=document.getElementById('case');select.innerHTML=cases.map(c=>`<option value="${c.key}">${c.label}</option>`).join('');select.value='three';
const frames=[...document.querySelectorAll('iframe')],fields=['case','field','context','content','padding','bounds','width','amount'];
function fit(frame){const available=frame.closest('.workspace').clientWidth,width=Number(frame.width)||1200,height=Number(frame.height)||700,scale=Math.min(1,available/width);Object.assign(frame.style,{width:`${width}px`,height:`${height}px`,transform:`scale(${scale})`});Object.assign(frame.parentElement.style,{width:`${width*scale}px`,height:`${height*scale}px`});}
function update(){const width=Math.max(320,Math.min(2400,Number(document.getElementById('width').value)||1200));for(const frame of frames){const q=new URLSearchParams({amount:frame.id==='baseline'?'none':document.getElementById('amount').value});for(const key of fields){if(key==='amount')continue;const n=document.getElementById(key);q.set(key,n.type==='checkbox'?String(n.checked):n.value);}if(frame.id==='percent'){const bits=Number(document.getElementById('amount').value);frame.title=`Composition with ${bits} ruler bits of vertical spacing`;document.getElementById('spacing-title').textContent=bits===0?'Zero vertical spacing':`${bits===1?'One':'Two'}-bit vertical spacing`;document.getElementById('spacing-description').textContent=bits===0?'Explicit zero reset on all direct items.':`Lower starts receive ${bits===1?'one bit':'two bits'}; the top row stays flush.`;}frame.width=width;frame.src=`./preview.html?${q}`;fit(frame);}}
for(const key of fields)document.getElementById(key).addEventListener('change',update);
document.getElementById('view').addEventListener('change',e=>{document.body.dataset.view=e.target.value;frames.forEach(fit);});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='vertical-spacing-size')return;const frame=frames.find(f=>f.contentWindow===e.source);if(!frame||!Number.isFinite(e.data.height))return;frame.height=Math.ceil(e.data.height);fit(frame);});
let pending=false;new ResizeObserver(()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;frames.forEach(fit);});}).observe(document.querySelector('.comparisons'));update();
